import { AnimatedIconFrame, type AnimatedIconProps } from "../icon-frame";
import "./monitor.css";

export function AnimatedMonitorIcon(props: AnimatedIconProps) {
  return (
    <AnimatedIconFrame name="monitor" {...props}>
      <rect data-part="screen" x="3" y="4" width="18" height="12.5" rx="2.5" />
      <path data-part="stand" d="M12 16.5V20M8.5 20h7" />
    </AnimatedIconFrame>
  );
}

:is([data-icon-hover] .animated-icon, .animated-icon[data-icon-hover], .animated-icon[data-play]) {
  &[data-icon="monitor"] {
    & [data-part="screen"] {
      --icon-pulse: scale(0.94);
      transform-origin: 12px 10.25px;
      animation-name: icon-pulse;
    }

    & [data-part="stand"] {
      --icon-y: 1px;
      --icon-delay: 80ms;
      animation-name: icon-nudge;
    }
  }
}
